import { MODES, type Mode } from "@/constants/modes";
import { useMemo } from "react";
import { View } from "react-native";
import {
  DefaultLight,
  EntitySelector,
  FilamentScene,
  FilamentView,
  ModelRenderer,
  RenderCallbackContext,
  useFilamentContext,
  useModel,
  type Float3,
  type RNFCamera,
} from "react-native-filament";
import type { SharedValue } from "react-native-reanimated";
import { useSharedValue as useFilamentSharedValue, type ISharedValue } from "react-native-worklets-core";
import { useFilamentBridge } from "./use-filament-bridge";

// Generated by scripts/build-globe.mjs
const GLOBE = require("../../../assets/models/globe.glb");

// One mode per quarter turn: four vehicles close the circle
const QUARTER = Math.PI / 2;

// The globe is scaled to radius 1 at the top of its land; oceans sit lower
const SURFACE = 1;

// Places on Earth (lat, lon) that line up with the wheel at rest: the jeep's
// spot on top and the boat's on the right. The bike gets the spot opposite
// the boat, and the camera faces the Atlantic.
const GLOBE_ORIENTATION = orientGlobe({ top: [56, 44], right: [-32, 68] });

const CAMERA = {
  distance: 5.4,
  // Horizontal, so the globe's size follows the view's width and a taller
  // view only adds room above and below
  fovDegrees: 30,
  // Looks slightly down on the globe; a full tilt adds or removes this much
  baseTiltDegrees: 12,
  tiltDegrees: 24,
  target: [0, 0.5, 0] as Float3,
};

// Idle sway of the whole world, so the vehicle on top keeps inching along
const IDLE_SWAY = 0.035;
const IDLE_PERIOD_S = 6;

type CameraWithFovDirection = RNFCamera & {
  setProjection(
    fov: number,
    aspect: number,
    near: number,
    far: number,
    direction: "horizontal" | "vertical"
  ): void;
};

export type GlobeStageProps = {
  offset: SharedValue<number>;
  tilt: SharedValue<number>;
  reducedMotion: boolean;
  width: number;
  height: number;
};

/** The globe and its four vehicles, rendered with Filament. */
export function GlobeStage(props: GlobeStageProps) {
  const style = useMemo(
    () => ({ width: props.width, height: props.height }),
    [props.width, props.height]
  );

  return (
    <View pointerEvents="none" style={style}>
      <FilamentScene>
        <Scene {...props} />
      </FilamentScene>
    </View>
  );
}

function Scene({ offset, tilt, reducedMotion, width, height }: GlobeStageProps) {
  const style = useMemo(() => ({ width, height }), [width, height]);
  const roll = useFilamentBridge(offset, 0);

  return (
    <FilamentView enableTransparentRendering pointerEvents="none" style={style}>
      <GlobeCamera tilt={tilt} aspect={width / height} />
      <DefaultLight />
      <Globe roll={roll} reducedMotion={reducedMotion} />
      {MODES.map((mode, index) => (
        <Vehicle
          key={mode.id}
          index={index}
          mode={mode}
          roll={roll}
          reducedMotion={reducedMotion}
        />
      ))}
    </FilamentView>
  );
}

function GlobeCamera({ tilt, aspect }: { tilt: SharedValue<number>; aspect: number }) {
  const { camera } = useFilamentContext();
  const filamentTilt = useFilamentBridge(tilt, 0);
  const projectionConfigured = useFilamentSharedValue(false);

  RenderCallbackContext.useRenderCallback(() => {
    "worklet";
    if (!projectionConfigured.value) {
      (camera as CameraWithFovDirection).setProjection(
        CAMERA.fovDegrees,
        aspect,
        0.1,
        100,
        "horizontal"
      );
      projectionConfigured.value = true;
    }
    const clamped = Math.max(-1, Math.min(1, filamentTilt.value));
    const angle = ((CAMERA.baseTiltDegrees + clamped * CAMERA.tiltDegrees) * Math.PI) / 180;
    camera.lookAt(
      [0, CAMERA.target[1] + Math.sin(angle) * CAMERA.distance, Math.cos(angle) * CAMERA.distance],
      CAMERA.target,
      [0, 1, 0]
    );
  }, [aspect, camera, filamentTilt, projectionConfigured]);

  return null;
}

function Globe({ roll, reducedMotion }: { roll: ISharedValue<number>; reducedMotion: boolean }) {
  const model = useModel(GLOBE);
  const { transformManager } = useFilamentContext();
  const entity = model.state === "loaded" ? model.rootEntity : undefined;
  const box = model.state === "loaded" ? model.boundingBox : undefined;

  RenderCallbackContext.useRenderCallback(
    ({ passedSeconds }) => {
      "worklet";
      if (entity == null || box == null) return;
      const radius = Math.max(box.halfExtent[0], box.halfExtent[1], box.halfExtent[2]);
      const scale = 1 / radius;
      const transform = transformManager
        .createIdentityMatrix()
        .scaling([scale, scale, scale])
        .rotate(GLOBE_ORIENTATION.angle, GLOBE_ORIENTATION.axis)
        .rotate(worldRoll(roll.value, passedSeconds, reducedMotion), [0, 0, 1]);
      transformManager.setTransform(entity, transform);
    },
    [box, entity, reducedMotion, roll, transformManager]
  );

  return null;
}

type VehicleProps = {
  index: number;
  mode: Mode;
  roll: ISharedValue<number>;
  reducedMotion: boolean;
};

function Vehicle({ index, mode, roll, reducedMotion }: VehicleProps) {
  const model = useModel(mode.model);
  const { transformManager } = useFilamentContext();
  const entity = model.state === "loaded" ? model.rootEntity : undefined;
  const box = model.state === "loaded" ? model.boundingBox : undefined;

  RenderCallbackContext.useRenderCallback(
    ({ passedSeconds }) => {
      "worklet";
      if (entity == null || box == null) return;
      const [cx, cy, cz] = box.center;
      const extent = Math.max(box.halfExtent[0], box.halfExtent[1], box.halfExtent[2]);
      const scale = mode.size / (2 * extent);

      // Where this vehicle sits on the wheel: the active one on top, its
      // neighbours peeking at the sides, the one opposite hidden
      const angle = wrapAngle(worldRoll(roll.value, passedSeconds, reducedMotion) - index * QUARTER);
      const show = Math.max(0, Math.min(1, 1.6 - Math.abs(angle) / QUARTER));
      // Off the top, the plane comes down to hug the globe so it stays on screen
      const focus = Math.max(0, 1 - Math.abs(angle) / QUARTER);
      const lift = mode.lift > 0 ? mode.lift * (0.15 + 0.85 * focus) : mode.lift;
      const idle = reducedMotion ? IDLE_STILL : idleMotion(mode.id, passedSeconds);

      // Every matrix op allocates on the native side, so keep the chain short:
      // centring and "wheels on the ground" share one translate, and the
      // uniform visibility scale folds into the size
      const size = scale * show;
      const transform = transformManager
        .createIdentityMatrix()
        .translate([-cx, -cy + box.halfExtent[1], -cz])
        .scaling([size, size, size])
        .rotate(mode.yaw, [0, 1, 0])
        .rotate(idle.bank, [1, 0, 0])
        .translate([0, SURFACE + lift + idle.bob, 0])
        .rotate(angle, [0, 0, 1]);
      transformManager.setTransform(entity, transform);
    },
    [box, entity, index, mode, reducedMotion, roll, transformManager]
  );

  if (model.state !== "loaded") return null;

  return (
    <ModelRenderer model={model}>
      {mode.hide?.map((name) => (
        <EntitySelector
          key={name}
          byName={name}
          scale={[0, 0, 0]}
          multiplyWithCurrentTransform={false}
        />
      ))}
    </ModelRenderer>
  );
}

const IDLE_STILL = { bob: 0, bank: 0 };

/** Each vehicle's own idle: the jeep bounces, the boat rocks, the plane banks. */
function idleMotion(id: Mode["id"], seconds: number) {
  "worklet";
  switch (id) {
    case "drive":
      return { bob: Math.abs(Math.sin(seconds * 9)) * 0.012, bank: 0 };
    case "sail":
      return { bob: Math.sin(seconds * 1.6) * 0.008, bank: Math.sin(seconds * 1.3) * 0.12 };
    case "fly":
      return { bob: Math.sin(seconds * 1.1) * 0.04, bank: Math.sin(seconds * 0.8) * 0.18 };
    default:
      return { bob: Math.abs(Math.sin(seconds * 6)) * 0.006, bank: Math.sin(seconds * 3) * 0.04 };
  }
}

/** The whole world's turn: one quarter per mode, plus a slow idle sway. */
function worldRoll(offset: number, seconds: number, reducedMotion: boolean) {
  "worklet";
  const sway = reducedMotion ? 0 : Math.sin((seconds / IDLE_PERIOD_S) * Math.PI * 2) * IDLE_SWAY;
  return offset * QUARTER + sway;
}

function wrapAngle(angle: number) {
  "worklet";
  return Math.atan2(Math.sin(angle), Math.cos(angle));
}

/**
 * The single rotation (angle + axis) that turns the globe so `top` faces up
 * (+Y) and `right` faces right (+X). Both are [lat, lon] in degrees, about 90°
 * apart. Uses the same axes as scripts/build-globe.mjs.
 */
function orientGlobe({ top, right }: { top: [number, number]; right: [number, number] }) {
  const toVector = ([lat, lon]: [number, number]): Float3 => {
    const la = (lat * Math.PI) / 180;
    const lo = (lon * Math.PI) / 180;
    return [Math.cos(la) * Math.sin(lo), Math.sin(la), Math.cos(la) * Math.cos(lo)];
  };
  const dot = (a: Float3, b: Float3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  const normalize = (v: Float3): Float3 => {
    const length = Math.hypot(...v);
    return [v[0] / length, v[1] / length, v[2] / length];
  };

  // An orthonormal frame: up, right made exactly perpendicular, and forward
  const up = toVector(top);
  const r = toVector(right);
  const side = normalize([r[0] - up[0] * dot(r, up), r[1] - up[1] * dot(r, up), r[2] - up[2] * dot(r, up)]);
  const forward: Float3 = [
    side[1] * up[2] - side[2] * up[1],
    side[2] * up[0] - side[0] * up[2],
    side[0] * up[1] - side[1] * up[0],
  ];

  // Rows of the rotation matrix are the frame's axes; read off angle and axis
  const m = [side, up, forward];
  const angle = Math.acos(Math.max(-1, Math.min(1, (m[0][0] + m[1][1] + m[2][2] - 1) / 2)));
  const axis = normalize([m[2][1] - m[1][2], m[0][2] - m[2][0], m[1][0] - m[0][1]]);
  return { angle, axis };
}
